  /* ==============================================================
    HOME.CSS — Home page-specific styles
    Requires global.css and common.css to be loaded first.
    Hero, Stats, Capabilities, Why Choose Us, Success Stories,
    Industries, Process, Blog, Testimonials, FAQ and Contact
    sections that are unique to Home.html.
    ================================================================= */

  /* ===== [UNUSED] Hero Section Styles — .hero-section =====
    None of these classes (.hero-section, .hero-title, .hero-copy-col, etc.)
    appear in Home.html. The live hero markup uses .hero (see the
    "===== Hero Section — .hero =====" block below). Kept for reference only. */

  :root {
    --primary-color: #1ca0e3;
    --dark-color: #000;
    --light-color: #f8f9fa;
    --accent-color: #0066cc;
    --text-color: #333;
    --border-color: #e0e0e0;
  }

  /* Hero Section Container */
  .hero-section {
    position: relative;
    padding: 80px 0;
    overflow: hidden;
    background: linear-gradient(135deg, #f5f7fa 0%, #fff 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
  }
  .hero-content .hero-cta .btn.primary:hover {
    background: #1588c7;
    border-color: #1588c7;
    box-shadow: 0 8px 24px rgba(28, 160, 227, .4);
    transform: translateY(-2px);
}
  .hero-content .hero-cta .btn {
    border-color: #FFFFFF;
    box-shadow: 0 4px 16px rgba(28, 160, 227, .3);
    color: #FFFFFF;
  }
.hero-content .hero-cta .btn:hover{
      box-shadow: rgba(28, 160, 227, 0.3) 0px 4px 16px;
      color: rgb(0, 83, 134);
      background: rgb(255, 255, 255);
      border-color: rgb(0, 83, 134);
  }
  .hero-container {
    position: relative;
    z-index: 1;
  }

  /* Background Dots Animation */
  .hero-bg-dots {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: radial-gradient(circle,
        rgba(28, 160, 227, 0.1) 1px,
        transparent 1px);
    background-size: 50px 50px;
    background-position:
      0 0,
      25px 25px;
    opacity: 0.5;
    z-index: 0;
    pointer-events: none;
  }

  /* Hero Row */
  .hero-row {
    gap: 60px;
    margin-top: 0;
  }

  /* Hero Copy Column */
  .hero-copy-col {
    display: flex;
    align-items: center;
    position: relative;
    z-index: 2;
  }

  .hero-copy {
    max-width: 600px;
    margin: 0 auto;
  }

  /* Eyebrow */
  .eyebrow {
    display: inline-block;
    font-size: 14px;
    font-weight: 600;
    color: #185686;
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 20px;
  }

  /* Hero Title */
  .hero-title {
    font-size: clamp(32px, 5vw, 56px);
    font-weight: 800;
    line-height: 1.2;
    margin-bottom: 24px;
    color: var(--dark-color);
    letter-spacing: -0.5px;
  }

  .word {
    display: inline;
    margin-right: 0.2em;
  }

  .word-accent {
    color: var(--primary-color);
    background: linear-gradient(135deg,
        var(--primary-color) 0%,
        var(--accent-color) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* Hero Subtitle */
  .hero-subtitle {
    font-size: 18px;
    line-height: 1.6;
    color: #666;
    margin-bottom: 40px;
    max-width: 500px;
    font-weight: 400;
  }

  /* CTA Buttons */
  .hero-cta-buttons {
    display: flex;
    gap: 16px;
    margin-bottom: 48px;
    flex-wrap: wrap;
  }

  .hero-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 12px 28px;
    font-size: 16px;
    font-weight: 600;
    border-radius: 6px;
    transition: all 0.3s ease;
    white-space: nowrap;
    text-decoration: none;
    cursor: pointer;
    border: 2px solid transparent;
  }

  .btn-primary.hero-btn {
    background: var(--primary-color);
    color: white;
    border: 2px solid var(--primary-color);
  }

  .btn-primary.hero-btn:hover {
    background: var(--accent-color);
    border-color: var(--accent-color);
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(28, 160, 227, 0.3);
  }

  .btn-outline-dark.hero-btn {
    background: transparent;
    color: var(--dark-color);
    border: 2px solid var(--border-color);
  }

  .btn-outline-dark.hero-btn:hover {
    background: var(--dark-color);
    color: white;
    border-color: var(--dark-color);
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  }

  .hero-content .hero-cta .btn.primary {
    color: #005386;
  }

  .hero-cta .btn.primary:hover {
    color: #fff;
  }

  .btn-arrow {
    width: 16px;
    height: 16px;
    transition: transform 0.3s ease;
  }

  .hero-btn:hover .btn-arrow {
    transform: translateX(4px);
  }

  /* Trust Badge */
  .hero-trust-badge {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px 20px;
    background: white;
    border-radius: 12px;
    border: 1px solid var(--border-color);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    max-width: fit-content;
  }

  .avatars-group {
    display: flex;
    align-items: center;
    gap: -8px;
  }

  .avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    border: 2px solid white;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    display: inline-block;
    margin-left: -8px;
    transition: transform 0.3s ease;
  }

  .avatar:first-child {
    margin-left: 0;
  }

  .avatar:hover {
    transform: translateY(-4px);
    z-index: 10;
  }

  .avatar-1 {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  }

  .avatar-2 {
    background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
  }

  .avatar-3 {
    background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
  }

  .avatar-4 {
    background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%);
  }

  .badge-content {
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .rating {
    font-size: 16px;
    font-weight: 700;
    color: var(--dark-color);
  }

  .stars {
    font-size: 14px;
    color: #ffc107;
    letter-spacing: 2px;
  }

  .badge-source {
    font-size: 12px;
    color: #999;
    font-weight: 500;
  }

  /* Hero Visual Column */
  .hero-visual-col {
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    z-index: 1;
  }

  .hero-image-wrapper .hero-badge.b2 {
    position: absolute;
    right: 0;
    top: -60px;
    transform: translateX(28%);
    z-index: 2;
    max-width: 550px;
  }

  .hero-image-wrapper .hero-badge.b3 {
    position: absolute;
    bottom: 0;
    pointer-events: none;
    left: 50%;
    transform: translate(-50%, 26%);
    max-width: 550px;
  }

  .hero-image-wrapper .hero-badge.b1 {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-10%, -50%);
  }

  .hero-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 12px;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
    animation: floatImage 6s ease-in-out infinite;
  }

  @keyframes floatImage {

    0%,
    100% {
      transform: translateY(0px);
    }

    50% {
      transform: translateY(-20px);
    }
  }

  .badge-1 {
    top: -20px;
    left: 20px;
    animation-delay: 0s;
  }

  .badge-2 {
    bottom: 20px;
    right: -20px;
    animation-delay: 0.5s;
  }

  @keyframes floatBadge {

    0%,
    100% {
      transform: translateY(0px) rotate(0deg);
    }

    50% {
      transform: translateY(-15px) rotate(5deg);
    }
  }

  .hero-copy {
    animation: slideInFromLeft 0.6s ease-out;
  }

  .hero-visual {
    z-index: 1;
    animation: slideInFromRight 0.6s ease-out 0.2s both;
  }

  /* Hero content animations */
  .hero .eyebrow {
    animation: fadeIn 0.6s ease-out 0.1s both;
  }

  .hero h1 {
    animation: fadeIn 0.6s ease-out 0.2s both;
  }

  .hero p.sub {
    animation: slideInFromLeft 0.6s ease-out 0.6s both;
  }

  .hero-cta {
    animation: slideInFromLeft 0.6s ease-out 0.7s both;
  }

  .clutch {
    animation: fadeIn 0.6s ease-out 0.8s both;
  }

  .eyebrow {
    animation: fadeIn 0.6s ease-out 0.3s both;
  }

  .hero-title {
    animation: fadeIn 0.6s ease-out 0.4s both;
  }

  .hero-subtitle {
    animation: fadeIn 0.6s ease-out 0.5s both;
  }

  .hero-cta-buttons {
    animation: fadeIn 0.6s ease-out 0.6s both;
  }

  .hero-trust-badge {
    animation: fadeIn 0.6s ease-out 0.7s both;
  }

  /* ===== Hero Section — .hero (id="hero") — ACTIVE implementation ===== */
  .hero {
    position: relative;
    background: var(--grad-navy);
    color: #fff;
    padding: calc(120px + 5vh) 0 90px;
    overflow: hidden;
  }

  .hero-bg-video {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    z-index: 0;
    filter: brightness(0.5);
  }

  .hero-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(90deg,
        rgba(10, 42, 74, 0.85) 0%,
        rgba(10, 42, 74, 0.7) 50%,
        rgba(10, 42, 74, 0.5) 100%);
    z-index: 1;
    pointer-events: none;
  }

  .hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(60% 80% at 78% 40%,
        rgba(28, 160, 227, 0.28),
        transparent 60%);
    pointer-events: none;
    z-index: 1;
  }

  .hero .dots {
    position: absolute;
    inset: 0;
    background-image: radial-gradient(rgba(255, 255, 255, 0.06) 1px,
        transparent 1px);
    background-size: 26px 26px;
    opacity: 0.5;
  }

  .hero .wrap {
    position: relative;
    z-index: 2;
  }

  .hero-grid {
    position: relative;
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    gap: 30px;
    align-items: center;
    z-index: 2;
  }

  .hero h1 {
    font-size: clamp(30px, 4.4vw, 50px);
    font-weight: 600;
    color: #fff;
    margin: 16px 0 20px;
    max-width: 680px;
  }

  .hero h1 .w {
    display: inline-block;
    opacity: 0;
    transform: translateY(24px);
    animation: heroWord 0.6s cubic-bezier(0.2, 0.7, 0.2, 1) forwards;
  }

  .hero h1 .w:nth-child(1) {
    animation-delay: 0.1s;
  }

  .hero h1 .w:nth-child(2) {
    animation-delay: 0.2s;
  }

  .hero h1 .w:nth-child(3) {
    animation-delay: 0.3s;
  }

  .hero h1 .w:nth-child(4) {
    animation-delay: 0.4s;
  }

  .hero h1 .w:nth-child(5) {
    animation-delay: 0.5s;
  }

  .hero h1 .highlight {
    color: var(--blue-2);
    background: linear-gradient(135deg, var(--blue-2) 0%, #1ca0e3 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  @keyframes heroWord {
    to {
      opacity: 1;
      transform: none;
    }
  }

  .hero .eyebrow {
    padding: 0;
    font-size: 14px;
    color: #fff;
  }

  .hero p.sub {
    color: #f2f2f2;
    font-size: 16px;
    max-width: 660px;
  }

  .hero-cta {
    display: flex;
    gap: 14px;
    flex-wrap: wrap;
    margin: 28px 0 92px;
  }

  .hero .clutch {
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .hero .avatars {
    display: flex;
    align-items: center;
  }

  .hero .avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #fff;
    margin-left: -10px;
  }

  .hero .avatar:first-child {
    margin-left: 0;
  }

  .hero .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  .hero .review-content {
    display: flex;
    flex-direction: column;
  }

  .hero .review-top {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .hero .rating {
    font-size: 14px;
    font-weight: 600;
    color: #fff;
    line-height: 1;
  }

  .hero .stars {
    color: #11a8ff;
    font-size: 16px;
    letter-spacing: 2px;
    line-height: 1;
  }

  .hero .review-bottom {
    margin-top: 4px;
    font-size: 14px;
    font-weight: 600;
    color: #fff;
    line-height: 1.2;
  }

  .hero-visual img {
    width: 100%;
    border-radius: 20px;
    animation: float 6s ease-in-out infinite;
  }

  @keyframes float {

    0%,
    100% {
      transform: translateY(0);
    }

    50% {
      transform: translateY(-14px);
    }
  }

