    color: #fff;
    background-repeat: no-repeat;
    background-size: cover;
    padding: 30px 0;
    position: relative;
  }

  .stats-section .stats-section__grid {
    display: flex;
    align-items: center;
  }

  .stats-section .stats-section__item {
    flex: 1;
    position: relative;
    text-align: center;
    padding: 0 20px;
  }

  .stats-section .stats-section__item+.stats-section__item::before {
    content: "";
    position: absolute;
    left: 0;
    top: 16%;
    height: 68%;
    width: 1px;
    background: #ffffff;
  }

  .stats-section .stats-section__number {
    font-family: "Poppins", sans-serif;
    font-weight: 600;
    font-size: clamp(28px, 3.4vw, 40px);
    display: block;
  }

  .stats-section .stats-section__label {
    color: #ffffff;
    font-size: 16px;
    margin-top: 4px;
  }

  /* ===== Capabilities Section — .capabilities-section (id="capabilities") ===== */
  .capabilities-section {
    padding: clamp(60px, 10vw, 90px) 0;
    background: #ffffff;
    position: relative;
  }

  .capabilities-header {
    margin-bottom: clamp(50px, 8vw, 100px);
    animation: fadeIn 0.6s ease-out 0.1s both;
  }

  .eyebrow {
    color: #185686;
    font-family: "Poppins", sans-serif;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 16px;
    display: inline-block;
  }

  .section-title {
    color: var(--ink);
    margin: 0;
    line-height: 1.2;
    letter-spacing: -0.02em;
    max-width: 80%;
  }

  .section-title .highlight {
    color: var(--blue-2);
    background: linear-gradient(135deg, var(--blue-2) 0%, #1ca0e3 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* Capabilities List */
  .capabilities-stack {
    position: relative;
  }

  .capability-card {
    position: sticky;
    top: 100px;
    z-index: calc(var(--card-index, 0) + 1);
    background: #ffffff;
    border-top: 1px solid #ececec;
    padding: clamp(28px, 4vw, 40px) 0;
    transition: border-color 0.35s ease;
  }

  .capability-card:last-child {
    border-bottom: 1px solid #ececec;
  }

  .capability-card:hover {
    border-color: rgba(28, 160, 227, 0.25);
  }

  .card-heading {
    display: flex;
    align-items: center;
    gap: 32px;
  }

  .card-number {
    font-family: "Poppins", sans-serif;
    font-size: clamp(24px, 2vw, 30px);
    font-weight: 600;
    color: #0093cf;
    letter-spacing: -0.02em;
    line-height: 1;
    display: flex;
  }

  .card-number .number-divider+span {
    font-size: clamp(24px, 2vw, 30px);
    color: #002237;
    font-weight: 600;
  }

  .number-divider {
    color: #0093cf;
    margin-right: 4px;
    font-weight: 400;
  }

  .card-title {
    font-family: "Poppins", sans-serif;
    font-size: clamp(24px, 2vw, 30px);
    font-weight: 600;
    color: #002237;
    margin: 0;
    line-height: 1.3;
    letter-spacing: -0.01em;
  }

  .card-description {
    font-family: "Poppins", sans-serif;
    font-size: 16px;
    line-height: 1.8;
    color: #3b5068;
    margin: 0;
    font-weight: 400;
    max-width: 382px;
    margin: 0 auto;
  }

  .card-image {
    border-radius: 14px;
    overflow: hidden;
    background: #f5f5f5;
    max-width: 432px;
    width: 100%;
    margin-left: auto;
  }

  .capability-image {
    width: 100%;
    height: 100%;
