  /* ---- Logo + "read more" row under the content card ---- */
  .testimonial-logo img {
    max-height: 40px;
    width: auto;
    opacity: 0.8;
  }

  .testi-bottom-row {
    position: absolute;
    bottom: 12px;
    right: 0;
