  .testi-bottom-row .testi-read-more {
    color: #FFFFFF;
  }

  .testi-bottom-row .testi-read-more:hover {
    color: #FF7700;
  }

  .testi-bottom-row .testi-read-more span {
    margin-left: 8px;
    width: 24px;
    height: 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  /* ---- Image-slide wrapper (Ken Burns-ish zoom on active slide) ---- */
  .testi-image-slide {
    outline: none;
  }

  .testi-image-slide .testimonial-left {
    position: relative;
    overflow: hidden;
  }

  .testi-image-slide .testimonial-left img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transform: scale(1.08);
    transition: transform 0.9s cubic-bezier(0.25, 0.46, 0.45, 0.94),
      filter 0.7s ease;
  }

  .testi-image-slider .slick-current .testimonial-left img {
    transform: scale(1);
    filter: brightness(1);
  }

  .testi-image-slide .testimonial-left img {
    transform: scale(1);
  }

  /* ---- Content slide wrapper ---- */
  .testi-content-slider {
    flex: 1;
    overflow: hidden;
  }

  .testi-content-slide {
    outline: none;
  }

  .testi-content-slide .testimonial-right {
    background: none;
    border-radius: 0 16px 16px 0;
    padding: 48px 44px;
    min-height: 400px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    box-sizing: border-box;
  }

  /* ==========================================================================
    New Rev CSS — 15 Jun — dual synchronized (image + content) slider layout
    ========================================================================== */

  .testimonials-main-slider-wrapper {
    align-items: center;
    display: flex;
    gap: 60px;
    padding: 20px 10px 10px;
  }

  .testimonials-image-wrapper {
    flex: 0 0 480px;
    max-width: 480px;
    position: relative;
  }

  .testimonials-content-wrapper {
    flex: 1;
    padding-right: 20px;
    width: 100%;
    max-width: calc(100% - 540px);
  }

  .testimonial-card-new {
    width: 100%;
  }

  .testimonials-image-slider .slick-slide {
    opacity: .4;
    transform: scale(.85);
    transition: all .4s ease;
  }

  .testimonials-image-slider .slick-center {
    opacity: 1;
    transform: scale(1);
    z-index: 10;
  }

  .testimonials-image-slider .slick-slide:not(.slick-center) {
    z-index: 1;
  }

  .testi-image-slide .testimonial-left {
    width: 100%;
    height: 400px;
    border-radius: 0;
  }

  .testimonials-section .testimonials-image-slider .slick-slide {
    margin: 0;
  }

  /* Depth/parallax stack for non-centered slides (later rule re-declares scale/opacity) */
  .testimonials-image-slider .slick-slide {
    transform: scale(0.8);
    opacity: 0.5;
    transition: all 0.4s ease;
    z-index: 1;
  }

  .testimonials-image-slider .slick-center,
  .testimonials-image-slider .slick-slide.slick-active {
    transform: scale(1);
    opacity: 1;
    z-index: 10;
    position: relative;
  }

  .testimonials-image-slider .slick-center+.slick-slide {
    transform: translateX(-40px) scale(0.9);
  }

  .testimonials-image-slider .slick-center~.slick-slide {
    transform: translateX(-80px) scale(0.8);
    transform: translateX(-320px) scale(0.8) rotate(5deg);
  }

